<?php
declare(strict_types=1);require_once __DIR__.'/database.php';
function queue_sms(string $accountType,int $accountId,string $phone,string $message,string $relatedType='',?int $relatedId=null):bool{$q=db()->prepare('SELECT is_enabled,credits_remaining FROM sms_entitlements WHERE account_type=? AND account_id=?');$q->execute([$accountType,$accountId]);$e=$q->fetch();if(!$e||!$e['is_enabled']||(int)$e['credits_remaining']<1)return false;db()->beginTransaction();try{db()->prepare('UPDATE sms_entitlements SET credits_remaining=credits_remaining-1,updated_at=now() WHERE account_type=? AND account_id=? AND credits_remaining>0')->execute([$accountType,$accountId]);db()->prepare("INSERT INTO sms_outbox(account_type,account_id,phone,message,related_type,related_id,status) VALUES(?,?,?,?,?,?,'queued')")->execute([$accountType,$accountId,$phone,$message,$relatedType,$relatedId]);db()->commit();return true;}catch(Throwable $x){if(db()->inTransaction())db()->rollBack();return false;}}
